import ee, math
ee.Initialize(project='earthsense-436113')

def detect_units_and_scale(mean_raw):
    # Returns (scale_factor, offset_to_C, unit_label)
    # mean_raw: raw mean SST value from dataset
    if mean_raw is None or (isinstance(mean_raw, float) and (math.isnan(mean_raw) or math.isinf(mean_raw))):
        return None
    if -5 <= mean_raw <= 50:
        return (1.0, 0.0, "C")
    if 240 <= mean_raw <= 330:
        return (1.0, -273.15, "K->C")
    # Handle potential scaled values (e.g., °C * 100)
    if -500 <= mean_raw <= 500:
        return (0.01, 0.0, "C*100")
    # Fallback: treat as Kelvin-like if very large
    if 330 < mean_raw < 400:
        return (1.0, -273.15, "K->C?")
    return (1.0, 0.0, "unknown")

def analyze_dataset(dataset_id, band, geom, scale_m):
    # Build baseline (Aug 1985-2012) and current (Aug 2019) collections
    base_col = (ee.ImageCollection(dataset_id)
                .select(band)
                .filterDate('1985-01-01', '2012-12-31')
                .filter(ee.Filter.calendarRange(8, 8, 'month'))
                .filterBounds(geom))
    cur_col = (ee.ImageCollection(dataset_id)
               .select(band)
               .filterDate('2019-08-01', '2019-09-01')
               .filter(ee.Filter.calendarRange(8, 8, 'month'))
               .filterBounds(geom))

    base_size = base_col.size().getInfo()
    cur_size = cur_col.size().getInfo()
    print(f"Dataset: {dataset_id}")
    print(f"Baseline Aug images (1985-2012): {base_size}, 2019 Aug images: {cur_size}")
    if base_size == 0 or cur_size == 0:
        return {'status': 'C1'}

    base_img = base_col.mean()
    cur_img = cur_col.mean()
    diff = cur_img.subtract(base_img)  # 2019 - climatology (raw units)

    # Valid pixel count on diff
    count = diff.reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom, scale=scale_m, maxPixels=1e9
    ).get(band).getInfo()
    if (count is None) or (int(count) == 0):
        print("No valid pixels after masking.")
        return {'status': 'C2'}

    # Raw means
    mean_base_raw = base_img.reduceRegion(
        reducer=ee.Reducer.mean(),
        geometry=geom, scale=scale_m, maxPixels=1e9
    ).get(band).getInfo()
    mean_cur_raw = cur_img.reduceRegion(
        reducer=ee.Reducer.mean(),
        geometry=geom, scale=scale_m, maxPixels=1e9
    ).get(band).getInfo()
    mean_diff_raw = diff.reduceRegion(
        reducer=ee.Reducer.mean(),
        geometry=geom, scale=scale_m, maxPixels=1e9
    ).get(band).getInfo()
    if any(v is None or (isinstance(v, float) and (math.isnan(v) or math.isinf(v))) for v in [mean_base_raw, mean_cur_raw, mean_diff_raw]):
        print("Calculation produced invalid (None/NaN/Inf) values.")
        return {'status': 'C3'}

    # Adaptive unit handling -> convert to °C-equivalent for reporting
    sf, off, unit = detect_units_and_scale(mean_base_raw)
    if sf is None:
        print("Unit detection failed.")
        return {'status': 'C3'}
    mean_base_c = mean_base_raw * sf + off
    mean_cur_c = mean_cur_raw * sf + off
    mean_diff_c = mean_diff_raw * sf  # offset cancels in difference

    # Cooler pixel fraction (sign is invariant to positive scaling/offset)
    cool_count = diff.lt(0).rename(band).reduceRegion(
        reducer=ee.Reducer.sum(),
        geometry=geom, scale=scale_m, maxPixels=1e9
    ).get(band).getInfo()
    cool_pct = (float(cool_count) / float(count)) * 100.0 if cool_count is not None and count else None

    # Light plausibility on Celsius equivalent anomaly
    if mean_diff_c is None or (abs(mean_diff_c) > 15):  # anomalies larger than 15°C are implausible
        print("Anomaly out of plausible range after conversion.")
        return {'status': 'C3'}

    print(f"Valid pixels: {int(count)}, Cooler pixels: {int(cool_count)} ({cool_pct:.1f}%)")
    print(f"Means (°C) - Baseline Aug: {mean_base_c:.2f}, 2019 Aug: {mean_cur_c:.2f}")
    print(f"Mean anomaly (2019 - baseline): {mean_diff_c:.2f} °C")

    is_cooler = (mean_diff_c < 0) and (cool_pct is not None and cool_pct > 50.0)
    return {'status': 'OK', 'is_cooler': is_cooler}

# Region: Northeastern Pacific (15–60N, 180–110W)
geom = ee.Geometry.Polygon(
    [[-180, 15], [-110, 15], [-110, 60], [-180, 60], [-180, 15]],
    None, False
)

datasets = [
    ('NOAA/CDR/OISST/V2_1', 'sst', 25000),
    ('NOAA/ERSST/V5', 'sst', 110000)
]

final_tag = None
for ds, band, scale in datasets:
    try:
        res = analyze_dataset(ds, band, geom, scale)
        status = res.get('status')
        if status == 'OK':
            final_tag = 'A' if res['is_cooler'] else 'B'
            break
        elif status == 'C1':
            continue  # try fallback dataset
        else:
            final_tag = status
            break
    except Exception as e:
        print(f"Processing error: {str(e)[:120]}")
        final_tag = 'D'
        break

if final_tag is None:
    final_tag = 'C1'

print(final_tag)
